import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, uniform, mix, smoothstep, Fn, time, hash, float, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = THREE;

  const group = new Group();
  group.userData.handlers = {};
  const cleanups = [];

  // --- palette (exact spec colors) ---
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  // --- atlas region ---
  const region =
    config.atlasRegion ??
    config.intent?.visualSpec?.atlasRegion ??
    { x: 0, y: 0, w: 512, h: 320 };
  const atlasW = config.atlasWidth ?? 512;
  const atlasH = config.atlasHeight ?? 320;
  const rx = region.x ?? 0;
  const ry = region.y ?? 0;
  const rw = region.w ?? 512;
  const rh = region.h ?? 320;
  const aspect = rw / rh;

  // --- backdrop: engineered gradient + accent glow + subtle grain ---
  const surfU = uniform(surface);
  const inkU = uniform(ink);
  const accentU = uniform(accent);

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = Fn(() => {
    const st = uv();
    const base = mix(surfU, inkU, smoothstep(float(0.0), float(1.0), st.y));
    const d = length(st.sub(vec2(0.5, 0.58)));
    const glow = float(1.0).sub(smoothstep(float(0.0), float(0.55), d)).mul(0.13);
    const col = base.add(accentU.mul(glow));
    const grain = hash(st.mul(vec2(820.0, 640.0)).add(time.mul(6.5))).sub(0.5).mul(0.035);
    return col.add(grain);
  })();

  const backdropGeo = new PlaneGeometry(9.0, 6.2);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.4);
  group.add(backdrop);
  cleanups.push(() => {
    backdropMat.dispose();
    backdropGeo.dispose();
  });

  // --- hero sprite plane ---
  const spriteH = 3.4;
  const spriteW = spriteH * aspect;
  const spriteGeo = new PlaneGeometry(spriteW, spriteH);
  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });
  const sprite = new Mesh(spriteGeo, spriteMat);
  sprite.position.set(0, 0, 0);
  sprite.renderOrder = 2;
  group.add(sprite);

  // entrance — weighted settle, no linear easing
  sprite.scale.set(0.96, 0.96, 1);
  spriteMat.opacity = 0;
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.to(spriteMat, { opacity: 1, duration: 0.7 }, 0)
    .to(sprite.scale, { x: 1.04, y: 1.04, duration: 0.7 }, 0)
    .to(sprite.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, 0.5);

  const imageUrl =
    config.imageUrl ??
    config.assets?.imageUrl ??
    config.intent?.visualSpec?.imageUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.repeat.set(rw / atlasW, rh / atlasH);
      // top-left origin atlas region -> flipY texture space
      tex.offset.set(rx / atlasW, 1.0 - (ry + rh) / atlasH);
      tex.needsUpdate = true;
      spriteMat.map = tex;
      spriteMat.needsUpdate = true;
    });
  }

  // --- soft contact glow plane (foreground accent depth) ---
  const glowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  glowMat.colorNode = Fn(() => {
    const st = uv();
    const d = length(st.sub(vec2(0.5, 0.5)));
    const a = float(1.0).sub(smoothstep(float(0.0), float(0.5), d)).mul(0.22);
    return vec3(accentU.r, accentU.g, accentU.b).mul(a);
  })();
  const glowGeo = new PlaneGeometry(spriteW * 1.25, spriteH * 1.25);
  const glowPlane = new Mesh(glowGeo, glowMat);
  glowPlane.position.set(0, 0, -0.05);
  glowPlane.renderOrder = 1;
  group.add(glowPlane);
  cleanups.push(() => {
    glowMat.dispose();
    glowGeo.dispose();
  });

  group.userData.cleanup = () => {
    tl.kill();
    cleanups.forEach((fn) => fn());
    spriteMat.dispose();
    spriteGeo.dispose();
    if (spriteMat.map) spriteMat.map.dispose();
  };

  return group;
}
